def positions(closes, n):
    # hold on day t if close t - 1 is above the mean of closes t - n to t - 1
    pos = []
    for t in range(len(closes)):
        if t < n:
            pos.append(0)
        else:
            window = closes[t - n:t]
            pos.append(1 if closes[t - 1] > sum(window) / n else 0)
    return pos


def test_no_lookahead():
    closes = [100.00, 102.00, 101.00, 104.00, 103.00, 105.00, 102.00, 106.00]
    base = positions(closes, 3)
    for k in range(len(closes)):
        for new in (1.00, 1000.00):          # a crash and a spike
            changed = closes[:k] + [new] + closes[k + 1:]
            assert positions(changed, 3)[:k + 1] == base[:k + 1]

