import pytest


def broker_fee(notional):
    if notional <= 0:
        raise ValueError("notional must be positive")
    pence = (round(notional * 100) + 500) // 1000  # 0.1%, half a penny up
    return min(max(pence, 495), 2500) / 100


def test_small_trade_pays_the_minimum():
    assert broker_fee(2_000.00) == pytest.approx(4.95)


def test_fee_is_a_tenth_of_a_percent_to_the_penny():
    assert broker_fee(8_765.43) == pytest.approx(8.77)  # 8.76543


def test_half_a_penny_rounds_up():
    assert broker_fee(12_345.00) == pytest.approx(12.35)  # 12.345


def test_large_trade_pays_the_cap():
    assert broker_fee(80_000.00) == pytest.approx(25.00)


@pytest.mark.parametrize("notional", [0.00, -500.00])
def test_zero_or_negative_notional_raises(notional):
    with pytest.raises(ValueError):
        broker_fee(notional)

