def _zq_binds(node, name):
    if isinstance(node, (_za.FunctionDef, _za.AsyncFunctionDef, _za.ClassDef)):
        return node.name == name
    if isinstance(node, (_za.Assign, _za.AnnAssign)):
        targets = node.targets if isinstance(node, _za.Assign) else [node.target]
        return any(isinstance(t, _za.Name) and t.id == name for t in targets)
